insert into public.publications (slug,title,abstract,year,journal,access_status,status,provenance) values ('sample-polar-observation-methods','Sample polar observation methods','Synthetic development publication abstract describing a demonstration approach to portal record discovery. This is not scientific research or an NCPOR publication.',2025,'Polar Portal Development Notes','OPEN','PUBLISHED','Synthetic demo content'),('southern-ocean-atmospheric-bridge','Southern Ocean atmospheric bridge: a demonstration record','Synthetic development publication for testing cross-content discovery. It contains no scientific findings or measurements.',2024,'Synthetic Outreach Review','OPEN','PUBLISHED','Synthetic demo content'),('sediment-core-context-notes','Sediment core context notes','Synthetic development publication used to demonstrate archival metadata and public access states.',2023,'Demo Archive Series','OPEN','PUBLISHED','Synthetic demo content') on conflict do nothing;
